import os
import re
import glob
import json
import time
import subprocess
from concurrent.futures import ThreadPoolExecutor, as_completed

def run_ocr(image_path):
    try:
        res = subprocess.run(['tesseract', image_path, 'stdout'], capture_output=True, text=True, check=True)
        return image_path, res.stdout
    except Exception as e:
        return image_path, f"ERROR: {str(e)}"

def format_time(seconds):
    h = int(seconds // 3600)
    m = int((seconds % 3600) // 60)
    s = int(seconds % 60)
    return f"{h:02d}:{m:02d}:{s:02d}"

def main():
    frame_dir = "/private/tmp/avb-pac12-antigravity-seven-field-20260827T200119Z/work/frames_2s"
    out_path = "/private/tmp/avb-pac12-antigravity-seven-field-20260827T200119Z/work/detailed_ocr_results.json"

    # Define ranges of interest
    ranges = [
        {"rotation": "Rotation 2 (ASU Beam)", "start": 2700, "end": 3420},
        {"rotation": "Rotation 3 (OSU Beam)", "start": 5040, "end": 5880},
        {"rotation": "Rotation 4 (Arizona Beam)", "start": 6840, "end": 7920}
    ]

    # Map target seconds to frame filenames
    target_files = {}
    for r in ranges:
        for sec in range(r["start"], r["end"] + 1, 2):
            frame_idx = int(round((sec - 1) / 2)) + 1
            filename = f"frame_{frame_idx:04d}.jpg"
            target_files[filename] = {
                "seconds": sec,
                "timestamp": format_time(sec),
                "rotation": r["rotation"],
                "file": filename,
                "path": os.path.join(frame_dir, filename)
            }

    print(f"Total target frames to OCR: {len(target_files)}")

    # Wait for the files to be extracted. Since extraction is running in the background,
    # we can check which files exist and process them. We keep running until all target files exist and are processed,
    # or until no new files are extracted for a while.
    results = {}
    if os.path.exists(out_path):
        try:
            with open(out_path) as f:
                old_data = json.load(f)
                for item in old_data:
                    results[item["file"]] = item
            print(f"Loaded {len(results)} existing results.")
        except Exception:
            pass

    executor = ThreadPoolExecutor(max_workers=10)
    active_futures = {}

    start_time = time.time()
    while True:
        # Check which target files are available on disk and not yet processed/processing
        available_targets = []
        for filename, info in target_files.items():
            if filename not in results and filename not in active_futures:
                if os.path.exists(info["path"]):
                    available_targets.append(info)

        if available_targets:
            print(f"Submitting {len(available_targets)} new frames for OCR.")
            for info in available_targets:
                f = executor.submit(run_ocr, info["path"])
                active_futures[info["path"]] = (f, info)

        # Reap finished futures
        done_paths = []
        for path, (fut, info) in list(active_futures.items()):
            if fut.done():
                path, text = fut.result()
                results[info["file"]] = {
                    "rotation": info["rotation"],
                    "seconds": info["seconds"],
                    "timestamp": info["timestamp"],
                    "file": info["file"],
                    "text": text
                }
                done_paths.append(path)
                del active_futures[path]

        if done_paths:
            # Save progress
            sorted_res = sorted(results.values(), key=lambda x: x["seconds"])
            with open(out_path, 'w') as f:
                json.dump(sorted_res, f, indent=2)
            print(f"Saved {len(results)} results.")

        # Exit condition: all target files are processed
        if len(results) >= len(target_files):
            print("All target frames processed!")
            break

        # If no active futures, and we waited too long or background extraction finished and no new files can exist
        # Let's see: we can check if task-239 is still running, or if we have waited a reasonable amount.
        # But let's just sleep and loop.
        time.sleep(2)

    sorted_res = sorted(results.values(), key=lambda x: x["seconds"])
    with open(out_path, 'w') as f:
        json.dump(sorted_res, f, indent=2)
    print("OCR ranges script finished successfully.")

if __name__ == "__main__":
    main()

